window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[295]={"id":"295","numero":295,"titre":"Prise en charge d'un malade cancéreux","objectifs":[{"id":"295-1","rang":"A","rubrique":"Définition","titre":"Connaître les généralités sur la prise en charge en cancérologie","contenu":"<p>La prise en charge d'un patient atteint de cancer est <strong>codifiée</strong>, <span class=\"kw-def\">pluridisciplinaire</span> et coordonnée tout au long du parcours de soins. Elle s'organise autour de structures et d'outils encadrés par l'<span class=\"kw-def\">INCa</span> et la <span class=\"kw-def\">RCP</span>.</p>\n      <table >\n        <thead><tr><th>Acteur</th><th>Définition &amp; missions</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">INCa</span><br>Institut National du Cancer</td>\n            <td>Agence sanitaire d'<strong>expertise</strong> au service de l'État, créée en <span class=\"kw-chiffre\">2005</span>.<br><strong>Recherche &amp; formation</strong> ; organisation et amélioration des soins ; mise en œuvre des dispositions réglementaires en cancérologie (<span class=\"kw-def\">dispositif d'annonce</span>, <span class=\"kw-def\">programme personnalisé de l'après-cancer</span>).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">RCP</span><br><span class=\"kw-def\">Réunion de Concertation Pluridisciplinaire</span></td>\n            <td>Réunion de professionnels de disciplines différentes prenant une décision <strong>conforme aux données actuelles de la science</strong> (référentiels + recommandations pour la pratique clinique).</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-def\">RCP</span> — règles à connaître :</strong></p>\n      <ul>\n        <li><span class=\"kw-alerte\">Tout patient</span> atteint de cancer doit être présenté en <span class=\"kw-def\">RCP</span> (visée diagnostique ou thérapeutique) — <strong>obl<span class=\"kw-chiffre\">iga</span>toire</strong>.</li>\n        <li>Présence de <span class=\"kw-chiffre\">≥ 3 médecins</span> de spécialités différentes ; à défaut, le dossier est représenté avec le spécialiste manquant dans <span class=\"kw-clinique\">les</span> plus brefs délais.</li>\n        <li>Inscription dans un <span class=\"kw-def\">réseau de cancérologie</span> (critère nécessaire).</li>\n        <li>Présence du <span class=\"kw-clinique\">médecin traitant</span> sollicitée mais <span class=\"kw-alerte\">non obligatoire</span>.</li>\n        <li>Décision <strong>tracée</strong> dans le dossier (date, proposition diagnostique/thérapeutique, noms et qualifications des médecins) et <strong>soumise au patient</strong>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège — démarrer avant la <span class=\"kw-def\">RCP</span>.</strong> Devant une <strong>prise en charge standard de validité incontestable</strong>, le traitement <span class=\"kw-alerte\">peut être mis en route sans attendre la RCP</span> ; le dossier doit ensuite être <strong>présenté pour être entériné</strong>, enregistré et archivé. La RCP n'est pas exclusive à la cancérologie (autres PEC complexes).</div>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Participer régulièrement à une <span class=\"kw-def\">RCP</span> permet de valider sa procédure de <span class=\"kw-def\">DPC</span> (développement professionnel continu).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 292 — Diagnostic des cancers · 294 — Traitement des cancers · 3 — Raisonnement et décision en médecine</em></p>","frequence":0},{"id":"295-2","rang":"A","rubrique":"Prise en charge","titre":"Connaître le dispositif d’annonce","contenu":"<p>Le <span class=\"kw-def\">dispositif d'annonce</span> est mis en place depuis le <strong>Plan cancer <span class=\"kw-chiffre\">2003-2007</span></strong> pour améliorer l'<span class=\"kw-clinique\">annonce de la maladie</span>. Il <span class=\"kw-alerte\">s'applique aussi aux rechutes de cancer</span> (++).</p>\n      <p>Il est construit autour de <strong><span class=\"kw-chiffre\">4 temps</span></strong> (chacun pouvant nécessiter plusieurs entretiens successifs) :</p>\n      <table >\n        <thead><tr><th>Temps</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1. Temps médical</strong></td>\n            <td>\n              <strong><span class=\"kw-def\">Annonce</span> du diagnostic</strong> et de la <span class=\"kw-def\">stratégie thérapeutique</span> via le <span class=\"kw-def\">PPS</span> (validé en <span class=\"kw-def\">RCP</span>).<br>\n              <strong>Risques</strong> à court / moyen / long terme et justification de l'option choisie.<br>\n// [13/06/2026] Cap « option C » LEVÉ : stars = comptage ⭐ brut de la source (plus de plafond à 5). hot = (stars <span class=\"kw-chiffre\">≥ 6</span>).\n              Proposition d'un <strong>2ᵉ avis médical</strong>.<br>\n              Proposition d'<strong>inclusion dans un <span class=\"kw-def\">essai thérapeutique</span></strong> le cas échéant.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>2. Temps d'accompagnement soignant</strong></td>\n            <td>Rencontre avec un soignant (<span class=\"kw-clinique\">infirmière d'annonce</span> le plus souvent) après la consultation médicale : informations sur le déroulement des soins, mise en relation avec d'autres professionnels (<span class=\"kw-clinique\">psychologue</span>, <span class=\"kw-clinique\">assistant social</span>).</td>\n          </tr>\n          <tr>\n            <td><strong>3. Temps d'accès aux soins de support</strong></td>\n            <td>Repérage des besoins spécifiques : prise en charge <span class=\"kw-clinique\">psycho-sociale</span> (psychologue, assistante sociale, associations, évaluation de la <span class=\"kw-clinique\">précarité</span>), <span class=\"kw-clinique\">kinésithérapie</span>…</td>\n          </tr>\n          <tr>\n            <td><strong>4. Temps d'articulation avec la médecine de ville</strong></td>\n            <td>Le <span class=\"kw-clinique\">médecin traitant</span> doit être <strong>informé en temps réel</strong>, dès le 1ᵉʳ temps de la PEC hospitalière ; il reste un interlocuteur privilégié associé au parcours.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-def\">Annonce</span> d'une maladie grave.</strong> L'annonce du cancer est un <strong>traumatisme</strong> aboutissant souvent à une <span class=\"kw-alerte\">sidération</span> : le patient ne peut entendre tout le discours lors de la consultation initiale. L'information doit être <strong>progressive, adaptée, personnalisée et répétée</strong> — mieux vécue, elle facilite l'adhésion.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 1 — La relation médecin-malade · <span class=\"kw-def\">annonce</span> d'une maladie grave</em></p>","frequence":3},{"id":"295-3","rang":"A","rubrique":"Définition","titre":"Connaître le Programme Personnalisé de Soins","contenu":"<p>Le <span class=\"kw-def\">Programme Personnalisé de Soins</span> (<span class=\"kw-def\">PPS</span>) est la <strong>pierre angulaire du <span class=\"kw-def\">dispositif d'annonce</span></strong>. C'est un <strong><span class=\"kw-def\">document écrit</span></strong> remis au patient au <strong><span class=\"kw-def\">début</span></strong> de sa prise en charge.</p>\n      <p>Il décrit de façon personnalisée le <strong>traitement prévu et validé en <span class=\"kw-def\">RCP</span></strong> et comprend notamment :</p>\n      <ul>\n        <li><strong>Coordonnées</strong> du <span class=\"kw-clinique\">médecin référent</span> et de l'<span class=\"kw-clinique\">équipe soignante référente</span> ;</li>\n        <li>Coordonnées de la <span class=\"kw-def\">personne de confiance</span> ;</li>\n        <li><strong><span class=\"kw-def\">Calendrier prévisionnel</span></strong> des soins et du <span class=\"kw-clinique\">suivi</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Ne pas confondre <span class=\"kw-def\">PPS</span> et PPAC.</strong> Le <span class=\"kw-def\">PPS</span> est remis <strong>au début</strong> du traitement (<span class=\"kw-def\">programme de soins</span>) ; le <span class=\"kw-def\">PPAC</span> — <span class=\"kw-def\">programme personnalisé de l'après-cancer</span> — est établi <strong>au terme</strong> du traitement (cf. objectif « phases du parcours de soins »).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 7 — Droits individuels et collectifs du patient</em></p>","frequence":0},{"id":"295-4","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités d’évaluation d’un patient cancéreux","contenu":"<p>L'évaluation d'un patient cancéreux est <strong>systématique</strong>, avant et pendant le traitement. Elle précise :</p>\n      <ul>\n        <li>La <span class=\"kw-clinique\">symptomatologie douloureuse</span> et la consommation d'<span class=\"kw-ttt\">antalgiques</span> ;</li>\n        <li>L'<span class=\"kw-clinique\">évolution</span> du <span class=\"kw-clinique\">poids</span>, de l'<span class=\"kw-clinique\">appétit</span> et la recherche de signes cliniques de <span class=\"kw-alerte\">dénutrition</span> ;</li>\n        <li>L'<strong>indice d'activité</strong> (<span class=\"kw-def\">Performance Status</span>, PS) selon l'échelle <span class=\"kw-def\">OMS/ECOG</span> (0 à 4) ou l'indice de <span class=\"kw-def\">Karnofsky</span> (<span class=\"kw-chiffre\">100 % = normal</span>, moins utilisé).</li>\n      </ul>\n      <table >\n        <thead><tr><th>OMS / ECOG</th><th>État</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">0</span></td><td>Asymptomatique</td><td>Activité normale, aucune restriction.</td></tr>\n          <tr><td><span class=\"kw-chiffre\">1</span></td><td>Symptomatique léger</td><td>Gêné pour <span class=\"kw-clinique\">les</span> efforts soutenus, mais déplacement seul + travail léger/sédentaire possible (bureau, ménage).</td></tr>\n          <tr><td><span class=\"kw-chiffre\">2</span></td><td>Symptomatique modéré</td><td><span class=\"kw-clinique\">Alité &lt; 50 %</span> de la journée ; autonome pour se déplacer et se soigner, mais incapable de travailler.</td></tr>\n          <tr><td><span class=\"kw-chiffre\">3</span></td><td>Symptomatique sévère</td><td><span class=\"kw-clinique\">Alité &gt; 50 %</span> de la journée, sans y être confiné ; autonomie limitée.</td></tr>\n          <tr><td><span class=\"kw-chiffre\">4</span></td><td>Totalement dépendant</td><td><span class=\"kw-alerte\">Confiné au lit ou au fauteuil</span>, incapable de prendre soin de soi.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Utilité décisionnelle.</strong> PS <span class=\"kw-chiffre\">0-1</span> → <span class=\"kw-ttt\">traitement actif</span> possible ; PS <span class=\"kw-chiffre\">2</span> → traitement avec adaptation ; PS <span class=\"kw-chiffre\">3-4</span> → <span class=\"kw-def\">pronostic</span> réservé, <strong>PEC palliative</strong> souvent privilégiée (et critère d'arrêt des traitements actifs).</div>","frequence":0},{"id":"295-5","rang":"A","rubrique":"Prise en charge","titre":"Connaître les grandes situations cliniques de prise en charge symptomatique","contenu":"<p>La stratégie dépend du <strong><span class=\"kw-def\">stade évolutif</span></strong> du cancer. On distingue <strong>trois grandes situations cliniques</strong>, qui conditionnent l'arbitrage <strong>bénéfice/risque</strong>.</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Objectif</th><th>Type de cancer</th><th>Traitements</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1. Curative</strong></td>\n            <td><span class=\"kw-alerte\">Guérison</span></td>\n            <td>Cancer <span class=\"kw-def\">localisé</span>, accessible à un traitement local</td>\n            <td><span class=\"kw-ttt\">Chirurgie</span> ; <span class=\"kw-ttt\">radiothérapie</span> ; <span class=\"kw-ttt\">chimio/hormonothérapie adjuvante</span> (réduit le risque de métastases)</td>\n          </tr>\n          <tr>\n            <td><strong>2. Intermédiaire</strong></td>\n            <td><span class=\"kw-clinique\">Survie prolongée</span> (parfois plusieurs années)</td>\n            <td>Maladie <span class=\"kw-def\">métastatique</span> mais contrôlable</td>\n            <td><span class=\"kw-ttt\">Chimiothérapie</span> ; <span class=\"kw-ttt\">immunothérapie / thérapies ciblées</span> ; <span class=\"kw-ttt\">chirurgie</span> ou <span class=\"kw-imagerie\">RT</span> si métastases peu nombreuses et accessibles</td>\n          </tr>\n          <tr>\n            <td><strong>3. Palliative</strong></td>\n            <td><span class=\"kw-clinique\">Qualité de vie</span> &amp; contrôle des symptômes</td>\n            <td>Cancer <span class=\"kw-def\">avancé non guérissable</span></td>\n            <td><span class=\"kw-ttt\">Soins symptomatiques</span> (<span class=\"kw-ttt\">antalgiques</span>, soins de support) ; antitumoraux parfois utilisés pour ralentir la progression</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Règle clé.</strong> La prise en charge par <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">soins de support / soins palliatifs</span> doit être proposée <span class=\"kw-alerte\">dès le diagnostic de maladie métastatique</span>, dans tous les cas. « Soins palliatifs » ≠ absence de prise en charge : c'est un <strong>recentrage sur le bien-être</strong> du patient.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 294 — Traitement des cancers · 139 — Soins palliatifs</em></p>","frequence":0},{"id":"295-6","rang":"A","rubrique":"Prise en charge","titre":"Connaître la manière d’évaluer et de caractériser la symptomatologie douloureuse en cancérologie et la mise en place des modalités de traitement","contenu":"<p>La recherche d'une <span class=\"kw-clinique\">symptomatologie douloureuse</span> doit être <strong>systématique</strong> chez tout patient atteint de cancer (avec la fatigue chronique, c'est un des symptômes <span class=\"kw-clinique\">les</span> plus fréquents).</p>\n      <p><strong>Évaluer et caractériser</strong> (à l'interrogatoire) :</p>\n      <ul>\n        <li><strong>Intensité</strong> : <span class=\"kw-clinique\">auto-évaluation</span> sur échelle visuelle analogique (<span class=\"kw-def\">EVA</span>) ;</li>\n        <li><strong>Caractère</strong> : <span class=\"kw-clinique\">aigu</span> ou <span class=\"kw-clinique\">chronique</span> ;</li>\n        <li><strong>Mécanisme</strong> : <span class=\"kw-def\">excès de nociception</span>, <span class=\"kw-def\">douleur neuropathique</span>, ou <span class=\"kw-def\">douleur mixte</span> ;</li>\n        <li><strong>Retentissement</strong> sur la qualité de vie (<span class=\"kw-clinique\">troubles du sommeil</span>, <span class=\"kw-clinique\">dépression</span>).</li>\n      </ul>\n      <table >\n        <thead><tr><th>Origine de la douleur</th><th>Mécanismes / exemples</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Atteinte tumorale</span></td><td><strong>Nociceptive :</strong> métastase osseuse<br><strong>Neuropathique :</strong> compression d'un tronc nerveux<br><strong>Mixte :</strong> <span class=\"kw-bio\">envahissement</span> pariétal thoracique</td></tr>\n          <tr><td><span class=\"kw-etio\">Séquelles des traitements</span></td><td><strong>Post-chirurgicales :</strong> cicatrice, capsulite rétractile après curage axillaire<br><strong>Post-<span class=\"kw-ttt\">chimiothérapie</span> :</strong> <span class=\"kw-clinique\">neuropathies périphériques</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Atteinte neurologique</span></td><td><span class=\"kw-clinique\">Céphalées</span> d'<span class=\"kw-alerte\">HTIC</span> (métastases cérébrales) ; <span class=\"kw-clinique\">méningite carcinomateuse</span> (symptômes mal systématisés)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Modalités de traitement :</strong></p>\n      <ul>\n        <li>Paliers OMS <span class=\"kw-chiffre\">1</span> et <span class=\"kw-chiffre\">2</span> d'efficacité <strong>rapidement limitée</strong> → recourir <span class=\"kw-alerte\">rapidement au palier 3</span> (<span class=\"kw-ttt\">morphiniques</span>).</li>\n        <li><strong>Co-<span class=\"kw-ttt\">antalgiques</span> :</strong> <span class=\"kw-ttt\">corticoïdes</span> (<span class=\"kw-alerte\">HTIC</span>, compression) ; <span class=\"kw-ttt\">AINS</span> (métastases osseuses — prudence chez ces patients fragiles) ; <span class=\"kw-ttt\">inhibiteurs de la résorption osseuse</span> (biphosphonates, dénosumab) ; antibiotiques si surinfection <span class=\"kw-etio\">tumorale</span> ; topiques locaux (douleur neuropathique localisée).</li>\n        <li><span class=\"kw-ttt\">Radiothérapie antalgique</span> et radiologie interventionnelle (cimentoplastie, radiofréquence, embolisation).</li>\n        <li>Recours à un <strong>médecin algologue</strong> pour <span class=\"kw-clinique\">les</span> douleurs complexes à composante neuropathique.</li>\n      </ul>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de cancérologie (Medline R2C).</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 135 — Thérapeutiques <span class=\"kw-ttt\">antalgiques</span> médicamenteuses et non médicamenteuses</em></p>","frequence":1},{"id":"295-7","rang":"B","rubrique":"Définition","titre":"Connaître la définition des soins de support en cancérologie","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">soins oncologiques de support</span> sont définis par l'<span class=\"kw-def\">INCa</span> comme « l'ensemble des <strong>soins et soutiens</strong> nécessaires aux personnes malades <strong>tout au long de la maladie</strong>, conjointement aux traitements onco-hématologiques spécifiques ».</p>\n      <ul>\n        <li>Objectif : assurer la <strong>meilleure qualité de vie</strong> possible et mieux prendre en charge <span class=\"kw-clinique\">les</span> effets secondaires des traitements ;</li>\n        <li><span class=\"kw-alerte\">Tous les patients</span> doivent y avoir accès, quel que soit le lieu de prise en charge ;</li>\n        <li>Évaluation des besoins <strong>dès l'<span class=\"kw-def\">annonce</span></strong>, reconduite au cours de l'<span class=\"kw-clinique\">évolution</span>.</li>\n      </ul>\n      <p><strong>Symptômes <span class=\"kw-clinique\">les</span> plus fréquents</strong> faisant appel à des mesures adaptées et spécifiques :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Fatigue (asthénie) chronique</span> — <span class=\"kw-chiffre\">50-80 %</span> des patients selon localisation/<span class=\"kw-def\">stade</span> ;</li>\n        <li><span class=\"kw-clinique\">Douleur</span> en cancérologie ;</li>\n        <li>Effets indésirables des chimiothérapies : <span class=\"kw-clinique\">NVCI</span>, <span class=\"kw-bio\">hématotoxicité</span>, <span class=\"kw-clinique\">toxicités cutanéo-muqueuses</span> ;</li>\n        <li><span class=\"kw-def\">Oncofertilité</span> (préservation de la fertilité).</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-clinique\">Asthénie</span> — réflexe.</strong> Éliminer d'abord <span class=\"kw-clinique\">les</span> <strong>causes curables</strong> : <span class=\"kw-bio\">anémie</span> / <span class=\"kw-bio\">carence martiale</span> (les plus fréquentes), <span class=\"kw-etio\">syndrome dépressif</span>, <span class=\"kw-etio\">hypothyroïdie</span> (fréquente après cancer du sein ou ORL), dénutrition, carence en <span class=\"kw-bio\">vitamine D</span>. L'<strong><span class=\"kw-ttt\">activité physique adaptée</span></strong> améliore significativement l'asthénie.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 135 — Thérapeutiques <span class=\"kw-ttt\">antalgiques</span> médicamenteuses et non médicamenteuses</em></p>","frequence":0},{"id":"295-8","rang":"B","rubrique":"Prise en charge","titre":"Soins de support : connaître les grands principes de prise en charge des principales complications des traitements en cancérologie","contenu":"<p><span class=\"kw-clinique\">Les</span> soins de support visent à prévenir et traiter les principales <strong>complications des traitements</strong> anticancéreux. Trois grands domaines : <span class=\"kw-clinique\">NVCI</span>, <span class=\"kw-bio\">hématotoxicité</span>, <span class=\"kw-clinique\">toxicités cutanéo-muqueuses</span>.</p>\n\n      <p><strong>① <span class=\"kw-clinique\">Nausées</span>-vomissements chimio-induits (NVCI)</strong></p>\n      <p>Trois types selon le délai : <span class=\"kw-clinique\">aigus</span> (<span class=\"kw-chiffre\">&lt; 24 h</span>, voie sérotoninergique 5HT3), <span class=\"kw-clinique\">retardés</span> (<span class=\"kw-chiffre\">&gt; 24 h</span>, récepteurs NK1) et <span class=\"kw-clinique\">anticipés</span> (avant l'administration, psychogènes).</p>\n      <table >\n        <thead><tr><th>Risque émétisant</th><th>Chimiothérapies</th><th>Prophylaxie</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Fort</strong> (<span class=\"kw-chiffre\">&gt; 90 %</span>)</td><td>Cisplatine, <span class=\"kw-ttt\">cyclophosphamide</span> forte dose, anthracyclines</td><td><span class=\"kw-ttt\">Anti-5HT3 (sétron)</span> + <span class=\"kw-ttt\">anti-NK1 (aprépitant)</span> + <span class=\"kw-ttt\">corticoïdes</span></td></tr>\n          <tr><td><strong>Moyen</strong> (<span class=\"kw-chiffre\">30-90 %</span>)</td><td>Oxaliplatine, carboplatine, <span class=\"kw-ttt\">cyclophosphamide</span> faible dose</td><td><span class=\"kw-ttt\">Anti-5HT3</span> + <span class=\"kw-ttt\">corticoïdes</span></td></tr>\n          <tr><td><strong>Faible</strong> (<span class=\"kw-chiffre\">10-30 %</span>)</td><td>5-FU, <span class=\"kw-ttt\">méthotrexate</span>, taxanes, gemcitabine</td><td><span class=\"kw-ttt\">Métoclopramide</span> ou sétron seul</td></tr>\n          <tr><td><strong>Minime</strong> (<span class=\"kw-chiffre\">&lt; 10 %</span>)</td><td>Bléomycine, vinblastine, vincristine</td><td>Pas de prophylaxie systématique</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Facteurs aggravants</strong> (renforcer la prophylaxie) : <span class=\"kw-clinique\">anxiété</span>, antécédents de NVCI, <span class=\"kw-clinique\">sexe féminin</span>, <span class=\"kw-clinique\">âge jeune</span>, administration en bolus (<span class=\"kw-bio\">vs</span> perfusion continue). Sétrons → <span class=\"kw-clinique\">céphalées</span>, constipation ; aprépitant → fatigue, ↑ transaminases. <span class=\"kw-clinique\">Les</span> <span class=\"kw-ttt\">BZD</span> sont utiles pour les <span class=\"kw-clinique\">vomissements</span> <strong>anticipés</strong>.</div>\n\n      <p><strong>② Hématotoxicité</strong></p>\n      <table >\n        <thead><tr><th>Lignée</th><th>Repères &amp; prise en charge</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\">Neutropénie</span></td>\n            <td>Nadir vers <span class=\"kw-chiffre\">J8</span>. Prophylaxie par <span class=\"kw-ttt\">G-CSF</span> :<br><strong>Primaire :</strong> risque de neutropénie sévère <span class=\"kw-chiffre\">&gt; 20 %</span>, ou <span class=\"kw-chiffre\">10-20 %</span> + contexte (âge, <span class=\"kw-def\">comorbidité</span>, <span class=\"kw-def\">isolement</span>).<br><strong>Secondaire :</strong> neutropénie <span class=\"kw-chiffre\">&lt; 0,5 G/L</span> ou <span class=\"kw-alerte\">neutropénie fébrile</span> au cycle précédent.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">Anémie</span></td>\n            <td>Apparaît sur <span class=\"kw-clinique\">les</span> semaines suivant le début du traitement, souvent multifactorielle. PEC des carences (<span class=\"kw-ttt\">fer IV</span>, <span class=\"kw-bio\">folates</span>, B12) ; <span class=\"kw-ttt\">EPO</span> si <span class=\"kw-chiffre\">Hb &lt; 10-11 g/dL</span> + anémie symptomatique ; <span class=\"kw-ttt\">transfusion</span> si <span class=\"kw-chiffre\">Hb &lt; 8 g/dL</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">Thrombopénie</span></td>\n            <td>Plus rare (tumeurs solides), plus tardive (après <span class=\"kw-chiffre\">J10</span>). Transfusion plaquettaire si <span class=\"kw-bio\">plaquettes</span> <span class=\"kw-chiffre\">&lt; 20 G/L</span> ou <span class=\"kw-alerte\">saignement actif</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>③ Toxicités cutanéo-muqueuses</strong></p>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Alopécie</span> :</strong> prévention par <span class=\"kw-ttt\">casque réfrigérant</span> (vasoconstriction du cuir chevelu réduisant la diffusion des cytotoxiques) ; <strong>prothèse capillaire</strong> partiellement remboursée par la Sécurité sociale.</li>\n        <li><strong><span class=\"kw-clinique\">Mucites</span> :</strong> hygiène bucco-dentaire rigoureuse + bains de bouche bicarbonatés ; aphtes souvent par <span class=\"kw-etio\">surinfection fongique</span> (antifongiques locaux) ; ne pas méconnaître <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">récurrences herpétiques</span>.</li>\n        <li><strong><span class=\"kw-ttt\">Anti-EGFR</span> :</strong> <span class=\"kw-clinique\">rash acnéiforme</span>, <span class=\"kw-clinique\">xérose</span>, fissures palmo-plantaires → éducation, crèmes émollientes + <span class=\"kw-ttt\">tétracyclines</span> (anti-acnéiques).</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 294 — Traitement des cancers · 296 — Agranulocytose médicamenteuse</em></p>","frequence":2},{"id":"295-9","rang":"B","rubrique":"Définition","titre":"Soins de support : connaître le concept de médecine alternative","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">médecines complémentaires et alternatives</span> (<span class=\"kw-def\">MCA</span>) regroupent « des approches, pratiques et produits de santé qui ne sont <strong>pas habituellement considérés comme faisant partie de la <span class=\"kw-def\">médecine conventionnelle</span></strong> ».</p>\n      <ul>\n        <li><strong>Complémentaire</strong> : utilisée <em>en plus</em> de la <span class=\"kw-def\">médecine conventionnelle</span> (ex. <span class=\"kw-clinique\">acupuncture</span> / <span class=\"kw-clinique\">auriculothérapie</span> pour <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">NVCI</span>) ;</li>\n        <li><strong>Alternative</strong> : proposée <em>à la place</em> du traitement conventionnel — risque de <span class=\"kw-alerte\">perte de chance</span>.</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Vigilance — <span class=\"kw-clinique\">automédication</span>.</strong> <span class=\"kw-alerte\">Phytothérapie</span> à risque d'<strong>interactions pharmacologiques</strong> (ex. <span class=\"kw-ttt\">millepertuis</span>, <span class=\"kw-def\">inducteur enzymatique</span>). <span class=\"kw-etio\">Régimes restrictifs</span> / « <span class=\"kw-etio\">jeûne thérapeutique</span> » → majoration de la <span class=\"kw-alerte\">dénutrition</span>. Toujours interroger le patient sur ses pratiques.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments (hors anti-<span class=\"kw-etio\">infectieux</span>)</em></p>","frequence":0},{"id":"295-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître les phases du parcours de soins","contenu":"<p>Le parcours de soins est <strong>codifié</strong> et se décline en <strong>phases successives</strong>, de l'entrée dans la maladie à l'éventuelle phase palliative.</p>\n      <table >\n        <thead><tr><th>Phase</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1. Entrée dans la maladie</strong></td><td><span class=\"kw-def\">RCP</span> diagnostique/thérapeutique + <span class=\"kw-def\">dispositif d'annonce</span> (<span class=\"kw-def\">PPS</span>) ; accompagnement psycho-social.</td></tr>\n          <tr><td><strong>2. Traitement &amp; PEC personnalisée</strong></td><td>Selon la situation clinique (curative / intermédiaire / palliative) ; soins de support associés.</td></tr>\n          <tr><td><strong>3. <span class=\"kw-def\">Surveillance</span> &amp; après-cancer</strong></td><td><span class=\"kw-def\">Surveillance</span> carcinologique + <span class=\"kw-def\">prévention tertiaire</span> ; remise du <span class=\"kw-def\">PPAC</span> au terme du traitement.</td></tr>\n          <tr><td><strong>4. Phase palliative</strong></td><td>Soins palliatifs (lois Leonetti / Claeys-Leonetti) ; question de l'arrêt des traitements actifs.</td></tr>\n        </tbody>\n      </table>\n\n      <p><strong>Programme Personnalisé de l'Après-Cancer (PPAC)</strong> — document remis au patient et adressé au médecin traitant, à <strong>3 volets</strong> :</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Surveillance</span> médicale :</strong> maladie, traitements reçus, complications, <span class=\"kw-clinique\">modalités de surveillance</span> ;</li>\n        <li><strong>Qualité de vie / soins de support :</strong> soutien <span class=\"kw-clinique\">psychologique</span>, soins esthétiques, conseils diététiques, <span class=\"kw-ttt\">activité physique adaptée</span>, <span class=\"kw-ttt\">sevrage tabagique</span> et des autres addictions ;</li>\n        <li><strong>Accompagnement social :</strong> maintien dans l'emploi, ouverture de droits (<span class=\"kw-def\">RQTH</span>, reconnaissance des <span class=\"kw-def\">maladies professionnelles</span>, « <span class=\"kw-def\">droit à l'oubli</span> »).</li>\n      </ul>\n\n      <p><strong><span class=\"kw-def\">Prévention tertiaire</span></strong> (agir, après le diagnostic, sur <span class=\"kw-clinique\">les</span> complications et les récidives) :</p>\n      <ul>\n        <li>Dépister <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">2ⁿᵈˢ cancers</span> et cibler leurs <span class=\"kw-def\">facteurs de risque</span> (<span class=\"kw-ttt\">sevrage tabagique</span> +++) ;</li>\n        <li>Prévenir <span class=\"kw-clinique\">les</span> complications iatrogènes et agir sur les FDR cardio-vasculaires (activité physique, <span class=\"kw-ttt\">réduction</span> du surpoids) ;</li>\n        <li>Orienter vers une consultation d'<span class=\"kw-def\">oncogénétique</span> <span class=\"kw-clinique\">les</span> patients à risque familial.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>Soins palliatifs &amp; arrêt des traitements actifs.</strong> Encadrés par <span class=\"kw-clinique\">les</span> lois <strong>Leonetti (22/04/2005)</strong> et <strong>Claeys-Leonetti (02/02/2016)</strong> : respect de la volonté du patient (<span class=\"kw-def\">directives anticipées</span>), interdiction de l'<span class=\"kw-alerte\">obstination déraisonnable</span>, interdiction de provoquer délibérément la mort. Un traitement actif (<span class=\"kw-ttt\">chimiothérapie</span>) <span class=\"kw-alerte\">ne doit pas être proposé si l'espérance de vie est &lt; 3 mois</span>. Autres critères d'arrêt : souhait du patient, <span class=\"kw-chiffre\">PS OMS 3-4</span>, balance bénéfice/risque défavorable, inefficacité des traitements antérieurs. Structures : <span class=\"kw-def\">USP</span>, lits identifiés, <span class=\"kw-def\">EMSP</span>, <span class=\"kw-def\">HAD</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 139 — Soins palliatifs : repères cliniques &amp; organisation · 140 — Soins palliatifs : accompagnement de la personne et de son entourage</em></p>","frequence":0}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://www.has-sante.fr/jcms/c_2806878/fr/reunion-de-concertation-pluridisciplinaire","label":"has-sante.fr"}],"cards":[{"i":"4d05cc2ed1f2","n":295,"o":"295-1","u":"Définition","t":"Connaître les généralités sur la prise en charge en cancérologie","q":"Qu'est-ce qu'une Réunion de Concertation Pluridisciplinaire (RCP) en cancérologie et quelles sont ses règles principales ?","a":"<p>La <strong>RCP</strong> est une réunion de professionnels de disciplines différentes qui prennent une décision conforme aux données actuelles de la science (référentiels et recommandations). Les règles principales sont :</p><ul><li>Tout patient atteint de cancer doit y être présenté, pour une visée diagnostique ou thérapeutique.</li><li>La présence d'au moins <strong>3 médecins de spécialités différentes</strong> est obligatoire.</li><li>La décision doit être <strong>tracée dans le dossier</strong> du patient et lui être soumise.</li><li>La RCP n'est pas exclusive à la cancérologie.</li></ul>"},{"i":"72d3d0f5ea2e","n":295,"o":"295-1","u":"Définition","t":"Connaître les généralités sur la prise en charge en cancérologie","q":"Comment définir les principes généraux de la prise en charge d'un patient atteint de cancer ?","a":"<p>La prise en charge d'un patient atteint de cancer est <strong>codifiée</strong>, <strong>pluridisciplinaire</strong> et <strong>coordonnée</strong>, et elle s'organise autour de structures et d'outils encadrés par l'<strong>INCa</strong> et la <strong>RCP</strong>.</p>"},{"i":"d44a8f455369","n":295,"o":"295-1","u":"Définition","t":"Connaître les généralités sur la prise en charge en cancérologie","q":"Dans quelles conditions un traitement anticancéreux peut-il être débuté avant une Réunion de Concertation Pluridisciplinaire (RCP) ?","a":"<p>Devant une <strong>prise en charge standard</strong> dont la validité est incontestable, le traitement peut être mis en route sans attendre la <strong>RCP</strong>. Cependant, le dossier doit ensuite être présenté en RCP pour être <strong>entériné, enregistré et archivé</strong>.</p>"},{"i":"d86313b56abd","n":295,"o":"295-1","u":"Définition","t":"Connaître les généralités sur la prise en charge en cancérologie","q":"Quel est le rôle de l'Institut National du Cancer (INCa) dans la prise en charge en cancérologie ?","a":"<p>L'<strong>INCa</strong> est une agence sanitaire d'expertise au service de l'État, créée en 2005. Ses missions incluent la recherche et la formation, l'organisation et l'amélioration des soins, et la mise en œuvre des dispositions réglementaires en cancérologie, telles que le <strong>dispositif d'annonce</strong> ou le <strong>programme personnalisé de l'après-cancer</strong>.</p>"},{"i":"127b2c2a3871","n":295,"o":"295-2","u":"Prise en charge","t":"Connaître le dispositif d’annonce","q":"Dans le contexte de la prise en charge d'un malade cancéreux, qu'est-ce que le dispositif d'annonce et quel est son objectif principal ?","a":"<p>Le dispositif d'annonce est une démarche structurée mise en place depuis le Plan cancer 2003-2007. Son objectif principal est d'<strong>améliorer l'annonce de la maladie cancéreuse</strong> au patient, y compris en cas de rechute.</p>"},{"i":"62f0a022a67f","n":295,"o":"295-2","u":"Prise en charge","t":"Connaître le dispositif d’annonce","q":"En quoi consiste le 'temps médical' du dispositif d'annonce pour le patient atteint de cancer ?","a":"<p>Le temps médical correspond à l'<strong>annonce du diagnostic</strong> et de la <strong>stratégie thérapeutique</strong>, validée en Réunion de Concertation Pluridisciplinaire (RCP). Le médecin expose les risques à court, moyen et long terme, justifie l'option choisie, et propose éventuellement un <strong>second avis médical</strong> ou une inclusion dans un <strong>essai thérapeutique</strong>.</p>"},{"i":"6354e78a6eb6","n":295,"o":"295-2","u":"Prise en charge","t":"Connaître le dispositif d’annonce","q":"Quels sont les quatre temps clés composant le dispositif d'annonce pour un patient cancéreux ?","a":"<ul><li>Le <strong>temps médical</strong>.</li><li>Le <strong>temps d'accompagnement soignant</strong>.</li><li>Le <strong>temps d'accès aux soins de support</strong>.</li><li>Le <strong>temps d'articulation avec la médecine de ville</strong>.</li></ul>"},{"i":"63693214afd5","n":295,"o":"295-2","u":"Prise en charge","t":"Connaître le dispositif d’annonce","q":"Quel est le rôle du 'temps d'accompagnement soignant' dans le dispositif d'annonce du cancer ?","a":"<p>Le temps d'accompagnement soignant intervient après la consultation médicale. Il s'agit d'une rencontre, le plus souvent avec une <strong>infirmière d'annonce</strong>, pour fournir des informations sur le déroulement des soins et orienter le patient vers d'autres professionnels comme un <strong>psychologue</strong> ou une <strong>assistante sociale</strong>.</p>"},{"i":"d49a7573b99f","n":295,"o":"295-2","u":"Prise en charge","t":"Connaître le dispositif d’annonce","q":"Pourquoi insiste-t-on sur la nécessité d'une information progressive, adaptée et répétée lors de l'annonce d'un cancer ?","a":"<p>L'annonce d'un cancer est un événement <strong>traumatisant</strong> qui peut provoquer une <strong>sidération</strong> chez le patient, l'empêchant d'entendre l'intégralité du discours initial. Une information progressive, adaptée, personnalisée et répétée permet une meilleure assimilation, facilite l'<strong>adhésion du patient</strong> à sa prise en charge et contribue à un meilleur vécu de la maladie.</p>"},{"i":"434c3695df54","n":295,"o":"295-3","u":"Définition","t":"Connaître le Programme Personnalisé de Soins","q":"Qu'est-ce que le Programme Personnalisé de Soins (PPS) dans la prise en charge d'un malade cancéreux ?","a":"<p>Le Programme Personnalisé de Soins (PPS) est la <strong>pierre angulaire du dispositif d'annonce</strong>. C'est un <strong>document écrit</strong> remis au patient au <strong>début de sa prise en charge</strong>, décrivant de façon personnalisée le traitement prévu et validé en Réunion de Concertation Pluridisciplinaire (RCP).</p>"},{"i":"4533e1198e20","n":295,"o":"295-3","u":"Définition","t":"Connaître le Programme Personnalisé de Soins","q":"Quelle est la différence entre le Programme Personnalisé de Soins (PPS) et le Programme Personnalisé de l'Après-Cancer (PPAC) ?","a":"<p>Le <strong>PPS</strong> est remis au <strong>début du traitement</strong> (programme de soins), tandis que le <strong>PPAC</strong> (Programme Personnalisé de l'Après-Cancer) est établi au <strong>terme du traitement</strong>, lors de la phase d'après-cancer.</p>"},{"i":"e394690e13b0","n":295,"o":"295-3","u":"Définition","t":"Connaître le Programme Personnalisé de Soins","q":"Quels sont les éléments clés que doit contenir un Programme Personnalisé de Soins (PPS) ?","a":"<ul><li>Les <strong>coordonnées du médecin référent</strong> et de l'équipe soignante référente.</li><li>Les <strong>coordonnées de la personne de confiance</strong>.</li><li>Un <strong>calendrier prévisionnel des soins</strong> et du suivi.</li></ul>"},{"i":"5ba0b06a40c5","n":295,"o":"295-4","u":"Prise en charge","t":"Connaître les modalités d’évaluation d’un patient cancéreux","q":"Quelle est l'utilité clinique et décisionnelle de l'échelle OMS/ECOG dans la prise en charge d'un patient cancéreux ?","a":"<p>L'échelle OMS/ECOG a une utilité <strong>décisionnelle majeure</strong> dans la prise en charge :</p><ul><li>Un <strong>PS 0-1</strong> permet généralement un <strong>traitement actif</strong>.</li><li>Un <strong>PS 2</strong> peut nécessiter un <strong>traitement avec adaptation</strong>.</li><li>Un <strong>PS 3-4</strong> indique un <strong>pronostic réservé</strong>, avec une prise en charge palliative souvent privilégiée et pouvant être un critère d'arrêt des traitements actifs.</li></ul>"},{"i":"61c677025fea","n":295,"o":"295-4","u":"Prise en charge","t":"Connaître les modalités d’évaluation d’un patient cancéreux","q":"Décrivez l'échelle OMS/ECOG utilisée pour évaluer le Performance Status chez un patient cancéreux.","a":"<p>L'échelle OMS/ECOG est un outil d'évaluation du Performance Status (PS) d'un patient cancéreux, allant de <strong>0 à 4</strong> :</p><ul><li><strong>PS 0</strong> : Patient <strong>asymptomatique</strong>, activité normale, aucune restriction.</li><li><strong>PS 1</strong> : Patient <strong>symptomatique léger</strong>, gêné pour les efforts soutenus mais se déplace seul et peut avoir une activité légère/sédentaire.</li><li><strong>PS 2</strong> : Patient <strong>symptomatique modéré</strong>, < 50% de la journée alité, autonome pour les soins mais incapable de travailler.</li><li><strong>PS 3</strong> : Patient <strong>symptomatique sévère</strong>, > 50% de la journée alité mais non confiné, autonomie limitée.</li><li><strong>PS 4</strong> : Patient <strong>totalement dépendant</strong>, confiné au lit ou au fauteuil, incapable de prendre soin de soi.</li></ul>"},{"i":"77a3d80cbe80","n":295,"o":"295-4","u":"Prise en charge","t":"Connaître les modalités d’évaluation d’un patient cancéreux","q":"Quand doit-on réaliser l'évaluation d'un patient cancéreux et quels sont les principaux axes de cette évaluation ?","a":"<p>L'évaluation d'un patient cancéreux est <strong>systématique</strong>, aussi bien <strong>avant</strong> que <strong>pendant le traitement</strong>. Elle précise :</p><ul><li>La <strong>symptomatologie douloureuse</strong> et la consommation d'antalgiques.</li><li>L'<strong>évolution du poids</strong>, de l'<strong>appétit</strong> et la recherche de signes cliniques de <strong>dénutrition</strong>.</li><li>L'<strong>indice d'activité (Performance Status, PS)</strong> selon l'échelle OMS/ECOG ou l'indice de Karnofsky.</li></ul>"},{"i":"05142c6b5062","n":295,"o":"295-5","u":"Prise en charge","t":"Connaître les grandes situations cliniques de prise en charge symptomatique","q":"À quel moment la prise en charge par les soins de support et les soins palliatifs doit-elle être proposée pour un patient atteint de cancer ?","a":"<p>La prise en charge par les <strong>soins de support</strong> et les <strong>soins palliatifs</strong> doit être proposée <strong>dès le diagnostic de maladie métastatique</strong>, dans tous les cas.</p>"},{"i":"1464b87214c1","n":295,"o":"295-5","u":"Prise en charge","t":"Connaître les grandes situations cliniques de prise en charge symptomatique","q":"Quels sont les traitements mis en œuvre dans la situation clinique palliative d'un cancer ?","a":"<ul><li><strong>Soins symptomatiques</strong> (notamment <strong>antalgiques</strong> et <strong>soins de support</strong>)</li><li>Des <strong>antitumoraux</strong> peuvent parfois être utilisés pour ralentir la progression.</li></ul>"},{"i":"1e492c9593ad","n":295,"o":"295-5","u":"Prise en charge","t":"Connaître les grandes situations cliniques de prise en charge symptomatique","q":"Quels sont les traitements envisagés dans la situation clinique intermédiaire de prise en charge d'un cancer ?","a":"<ul><li><strong>Chimiothérapie</strong></li><li><strong>Immunothérapie</strong> ou <strong>thérapies ciblées</strong></li><li><strong>Chirurgie</strong> ou <strong>radiothérapie</strong>, si les métastases sont peu nombreuses et accessibles.</li></ul>"},{"i":"22affae6d232","n":295,"o":"295-5","u":"Prise en charge","t":"Connaître les grandes situations cliniques de prise en charge symptomatique","q":"Décrivez la situation clinique « intermédiaire » de prise en charge d'un cancer, son objectif et les types de pathologies visées.","a":"<p>La situation clinique « intermédiaire » a pour objectif une <strong>survie prolongée</strong>, parfois de plusieurs années. Elle concerne les maladies <strong>métastatiques mais contrôlables</strong>.</p>"},{"i":"5c7b2ff60e24","n":295,"o":"295-5","u":"Prise en charge","t":"Connaître les grandes situations cliniques de prise en charge symptomatique","q":"Quelle est la première situation clinique de prise en charge d'un cancer, son objectif et son type de cancer associé ?","a":"<p>La première situation clinique est la prise en charge à visée <strong>curative</strong>. Son objectif est la <strong>guérison</strong> et elle concerne les cancers <strong>localisés</strong>, accessibles à un traitement local.</p>"},{"i":"8bbc2688225d","n":295,"o":"295-5","u":"Prise en charge","t":"Connaître les grandes situations cliniques de prise en charge symptomatique","q":"Quelle est la situation clinique palliative de prise en charge d'un cancer, quel est son objectif et quels types de cancers sont concernés ?","a":"<p>La situation clinique <strong>palliative</strong> a pour objectif la <strong>qualité de vie</strong> et le <strong>contrôle des symptômes</strong>. Elle concerne les cancers <strong>avancés et non guérissables</strong>.</p>"},{"i":"97c0f5bc0952","n":295,"o":"295-5","u":"Prise en charge","t":"Connaître les grandes situations cliniques de prise en charge symptomatique","q":"Quels sont les traitements typiques de la prise en charge curative d'un cancer ?","a":"<ul><li><strong>Chirurgie</strong></li><li><strong>Radiothérapie</strong></li><li><strong>Chimiothérapie</strong> ou <strong>hormonothérapie adjuvante</strong> pour réduire le risque de métastases.</li></ul>"},{"i":"24a8b2175c95","n":295,"o":"295-6","u":"Prise en charge","t":"Connaître la manière d’évaluer et de caractériser la symptomatologie douloureuse en cancérologie et la mise en place des modalités de traitement","q":"Quelles sont les principales origines de la douleur en cancérologie, et quels exemples illustrent leurs mécanismes ?","a":"<p>Les origines de la douleur en cancérologie sont multiples :</p><ul><li><strong>Atteinte tumorale</strong> :<ul><li><strong>Nociceptive</strong> : en cas de <strong>métastase osseuse</strong>.</li><li><strong>Neuropathique</strong> : due à une <strong>compression d'un tronc nerveux</strong>.</li><li><strong>Mixte</strong> : comme un <strong>envahissement pariétal thoracique</strong>.</li></ul></li><li><strong>Séquelles des traitements</strong> :<ul><li><strong>Post-chirurgicales</strong> : cicatrice, capsulite rétractile après curage axillaire.</li><li><strong>Post-chimiothérapie</strong> : <strong>neuropathies périphériques</strong>.</li></ul></li><li><strong>Atteinte neurologique</strong> :<ul><li><strong>Céphalées d'HTIC</strong> (en cas de métastases cérébrales).</li><li><strong>Méningite carcinomateuse</strong> (avec des symptômes mal systématisés).</li></ul></li></ul>"},{"i":"c6c449999b1c","n":295,"o":"295-6","u":"Prise en charge","t":"Connaître la manière d’évaluer et de caractériser la symptomatologie douloureuse en cancérologie et la mise en place des modalités de traitement","q":"Quelles sont les modalités de traitement des douleurs cancéreuses, en dehors des antalgiques des paliers de l'OMS ?","a":"<p>En complément des antalgiques des paliers de l'OMS (où l'on doit recourir rapidement au <strong>palier 3 morphiniques</strong> si les paliers 1 et 2 sont inefficaces), on utilise des <strong>co-antalgiques</strong> et d'autres approches :</p><ul><li><strong>Corticoïdes</strong> : pour l'<strong>HTIC</strong> ou les compressions.</li><li><strong>AINS</strong> : pour les <strong>métastases osseuses</strong> (avec prudence).</li><li><strong>Inhibiteurs de la résorption osseuse</strong> : <strong>biphosphonates</strong>, <strong>dénosumab</strong>.</li><li><strong>Antibiotiques</strong> : si surinfection tumorale.</li><li><strong>Topiques locaux</strong> : pour la douleur neuropathique localisée.</li><li>La <strong>radiothérapie antalgique</strong>.</li><li>La <strong>radiologie interventionnelle</strong> (cimentoplastie, radiofréquence, embolisation).</li><li>Le recours à un <strong>médecin algologue</strong> pour les douleurs complexes à composante neuropathique.</li></ul>"},{"i":"d87d2b1dd503","n":295,"o":"295-6","u":"Prise en charge","t":"Connaître la manière d’évaluer et de caractériser la symptomatologie douloureuse en cancérologie et la mise en place des modalités de traitement","q":"Comment évaluer et caractériser la symptomatologie douloureuse chez un patient cancéreux ?","a":"<p>L'évaluation de la douleur chez un patient cancéreux se fait par l'interrogatoire et doit caractériser :</p><ul><li>Son <strong>intensité</strong> : auto-évaluation sur <strong>échelle visuelle analogique (EVA)</strong>.</li><li>Son <strong>caractère</strong> : aigu ou chronique.</li><li>Son <strong>mécanisme</strong> : <strong>excès de nociception</strong>, <strong>douleur neuropathique</strong>, ou <strong>douleur mixte</strong>.</li><li>Son <strong>retentissement sur la qualité de vie</strong> (troubles du sommeil, dépression).</li></ul>"}]};